import{_ as s,a0 as r,w as p,s as a,I as o,x as e,a1 as n,A as i,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"去中心化的消息應用 Riot 改名為 Element | LCTT x X-CMD","titleTemplate":false,"description":"去中心化的消息應用 Riot 改名為 Element | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"去中心化的消息應用 Riot 改名為 Element | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"去中心化的消息應用 Riot 改名為 Element | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200717 Decentralized Messaging App Riot Rebrands to Element","title":"去中心化的消息應用 Riot 改名為 Element","tag":"202008","desc":""},"relativePath":"202008/20200717 Decentralized Messaging App Riot Rebrands to Element.md","filePath":"[post].md"}'),d={name:"202008/20200717 Decentralized Messaging App Riot Rebrands to Element.md"};function u(f,t,R,E,g,x){const l=r("Link");return p(),a("div",null,[t[24]||(t[24]=o("h1",{id:"去中心化的消息應用-riot-改名為-element",tabindex:"-1"},[e("去中心化的消息應用 Riot 改名為 Element "),o("a",{class:"header-anchor",href:"#去中心化的消息應用-riot-改名為-element","aria-label":"Permalink to “去中心化的消息應用 Riot 改名為 Element”"},"​")],-1)),t[25]||(t[25]=o("p",null,"Riot 曾經是，現在也是一款基於開源 Matrix 協議的去中心化即時通訊應用。",-1)),o("p",null,[t[1]||(t[1]=e("6 月底，Riot 即時通訊客户端宣佈將改名。他們透露，他們的新名字是 ",-1)),n(l,{href:"https://element.io/"},{default:i(()=>[...t[0]||(t[0]=[e("Element",-1)])]),_:1}),t[2]||(t[2]=e("。讓我們來看看 Riot 為什麼要改名，還有哪些要改。",-1))]),t[26]||(t[26]=o("h3",{id:"為什麼從-riot-改名為-element",tabindex:"-1"},[e("為什麼從 Riot 改名為 Element？ "),o("a",{class:"header-anchor",href:"#為什麼從-riot-改名為-element","aria-label":"Permalink to “為什麼從 Riot 改名為 Element？”"},"​")],-1)),t[27]||(t[27]=o("p",null,[o("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/07/riot-to-element.png?ssl=1",alt:""})],-1)),t[28]||(t[28]=o("p",null,"在説到最新的公告之前，我們先來看看他們當初為什麼要改名。",-1)),o("p",null,[t[4]||(t[4]=e("根據 6 月 23 日的一篇",-1)),n(l,{href:"https://element.io/blog/the-world-is-changing/"},{default:i(()=>[...t[3]||(t[3]=[e("Blog文章",-1)])]),_:1}),t[5]||(t[5]=e("，該組織改名有三個原因。",-1))]),o("p",null,[t[7]||(t[7]=e("首先，他們表示“某大型遊戲公司”曾多次阻止他們註冊 Riot 和 Riot.im 產品名稱的商標。如果要我猜的話，他們可能指的就是這家",-1)),n(l,{href:"https://en.wikipedia.org/wiki/Riot_Games"},{default:i(()=>[...t[6]||(t[6]=[e("“遊戲公司”",-1)])]),_:1}),t[8]||(t[8]=e("）。",-1))]),t[29]||(t[29]=m('<p>其次，他們選擇 Riot 這個名字的初衷是為了“喚起一些破壞性和活力的東西”。他們擔心人們反而認為這個應用是“專注於暴力”。我想，當前的情形下，這個名字並不算好。</p><p>第三，他們希望澄清 Riot 涉及的眾多品牌名稱所造成的混亂。例如，Riot 是由一家名為 New Vector 的公司創建的，而 Riot 是託管在 Modular 上，Modular 也是 New Vector 的產品。他們希望簡化他們的命名系統，以避免混淆潛在客户。當人們尋找消息解決方案時，他們希望他們只需要尋找一個名字：Element。</p><h3 id="元素即一切" tabindex="-1">元素即一切 <a class="header-anchor" href="#元素即一切" aria-label="Permalink to “元素即一切”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/07/element-desktop.jpg?ssl=1" alt=""></p><p>從 7 月 15 日開始，該應用的名稱和公司的名稱已經改為 Element（元素）。他們的 Matrix 託管服務現在將被稱為 Element Matrix Services。他們的公告很好地總結了這一點。</p><blockquote><p>“對於那些第一次發現我們的人來説，Element 是 Matrix 通信網絡中的旗艦級安全協作應用。Element 讓你擁有自己的端到端加密聊天服務器，同時還能與更廣泛的 Matrix 網絡中的其他人連接。”</p></blockquote><p>他們之所以選擇 Element 這個名字，是因為它“反映了我們在設計 RiotX 時對簡單和清晰的強調；這個名字突出了我們一心一意將 Element 打造成可以想像的最優雅和最實用的主流通訊應用的使命”。他們還説，他們想要一個“能喚起數據所有權和自我主權的概念”的名字。他們還認為這是一個很酷的名字。</p><h3 id="除了改個名之外" tabindex="-1">除了改個名之外 <a class="header-anchor" href="#除了改個名之外" aria-label="Permalink to “除了改個名之外”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/07/element-apps.jpg?ssl=1" alt=""></p><p>最近的公告也表明，此舉不僅僅是簡單的改名。Element 還發布了“新一代安卓版 Matrix 客户端”。該客户端的前身是 RiotX，現在改名為 Element。（還有呢？）它對以前的客户端進行了徹底的重寫，現在支持 VoIP 通話和小部件。Element 還將在 iOS 上推出，支持 iOS 13，並提供“全新的推送通知支持”。</p><p>Element Web 客户端也得到了一些關愛，更新了 UI 和新的更容易閲讀的字體。他們還“重寫了房間列表控件 —— 增加了房間預覽（!!）、按字母順序排列、可調整列表大小、改進的通知用户界面等”。他們還開始努力改進端到端加密。</p><h3 id="最後思考" tabindex="-1">最後思考 <a class="header-anchor" href="#最後思考" aria-label="Permalink to “最後思考”">​</a></h3><p>Element 公司的人邁出了一大步，做出了這樣的重大改名。他們可能會在短期內失去一些客户。（這可能主要是由於出於某種原因沒有意識到名稱的改變，或者不喜歡改變）。然而從長遠來看，品牌簡化將幫助他們脱穎而出。</p><p>我唯一要提到的負面説明是，這是他們在該應用歷史上的第三次改名。在 2016 年發佈時，它最初被命名為 Vector。當年晚些時候改名為 Riot。希望 Element 能一直用下去。</p><hr>',15)),o("p",null,[t[10]||(t[10]=e("via: ",-1)),n(l,{href:"https://itsfoss.com/riot-to-element/"},{default:i(()=>[...t[9]||(t[9]=[e("https://itsfoss.com/riot-to-element/",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("作者：",-1)),n(l,{href:"https://itsfoss.com/author/john/"},{default:i(()=>[...t[11]||(t[11]=[e("John Paul",-1)])]),_:1}),t[16]||(t[16]=e(" 選題：",-1)),n(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[12]||(t[12]=[e("lujun9972",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),n(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[21]||(t[21]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創編譯，",-1)),n(l,{href:"https://linux.cn/"},{default:i(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const C=s(d,[["render",u]]);export{w as __pageData,C as default};
